use std::panic::{catch_unwind,AssertUnwindSafe};use std::sync::{mpsc,Arc,Mutex};use std::thread::{self,JoinHandle};type Job=Box<dyn FnOnce()+Send+'static>;enum Message{Run(Job),Shutdown}
#[derive(Debug,Clone,PartialEq,Eq)]pub enum WorkerError{ZeroWorkers,WorkerStopped,TaskPanicked}
impl std::fmt::Display for WorkerError{fn fmt(&self,f:&mut std::fmt::Formatter<'_>)->std::fmt::Result{write!(f,"{:?}",self)}}impl std::error::Error for WorkerError{}
pub struct TaskHandle<R>{rx:mpsc::Receiver<Result<R,WorkerError>>}impl<R>TaskHandle<R>{pub fn wait(self)->Result<R,WorkerError>{self.rx.recv().map_err(|_|WorkerError::WorkerStopped)?}}
pub struct WorkerPool{tx:mpsc::Sender<Message>,threads:Vec<JoinHandle<()>>}
impl WorkerPool{pub fn new(n:usize)->Result<Self,WorkerError>{if n==0{return Err(WorkerError::ZeroWorkers)}let(tx,rx)=mpsc::channel();let rx=Arc::new(Mutex::new(rx));let mut threads=Vec::new();for i in 0..n{let r=rx.clone();threads.push(thread::Builder::new().name(format!("nexa-worker-{i}")).spawn(move||loop{let m={let g=match r.lock(){Ok(g)=>g,Err(_)=>break};g.recv()};match m{Ok(Message::Run(j))=>j(),Ok(Message::Shutdown)|Err(_)=>break}}).map_err(|_|WorkerError::WorkerStopped)?);}Ok(Self{tx,threads})}
pub fn submit<F,R>(&self,f:F)->Result<TaskHandle<R>,WorkerError>where F:FnOnce()->Result<R,WorkerError>+Send+'static,R:Send+'static{let(tx,rx)=mpsc::channel();let job=Box::new(move||{let v=catch_unwind(AssertUnwindSafe(f)).unwrap_or(Err(WorkerError::TaskPanicked));let _=tx.send(v);});self.tx.send(Message::Run(job)).map_err(|_|WorkerError::WorkerStopped)?;Ok(TaskHandle{rx})}
pub fn execute<F,R>(&self,f:F)->Result<R,WorkerError>where F:FnOnce()->R+Send+'static,R:Send+'static{self.submit(move||Ok(f()))?.wait()}pub fn size(&self)->usize{self.threads.len()}}
impl Drop for WorkerPool{fn drop(&mut self){for _ in 0..self.threads.len(){let _=self.tx.send(Message::Shutdown);}for h in self.threads.drain(..){let _=h.join();}}}
#[cfg(test)]mod tests{use super::*;#[test]fn task(){let p=WorkerPool::new(2).unwrap();assert_eq!(p.execute(||42).unwrap(),42)}#[test]fn panic_isolated(){let p=WorkerPool::new(1).unwrap();assert_eq!(p.execute(||panic!("test")),Err(WorkerError::TaskPanicked));assert_eq!(p.execute(||7).unwrap(),7)}#[test]fn zero_rejected(){assert_eq!(WorkerPool::new(0).err(),Some(WorkerError::ZeroWorkers))}}